package com.xdownload.mobile;
import android.app.*;import android.os.*;import android.webkit.*;import android.widget.*;import android.view.*;import android.net.Uri;
public final class PrivateBrowserActivity extends Activity{
 static boolean initialized=false;WebView web;EditText address;
 @Override public void onCreate(Bundle b){super.onCreate(b);if(!initialized){WebView.setDataDirectorySuffix("private");initialized=true;}CookieManager cm=CookieManager.getInstance();cm.setAcceptCookie(false);cm.removeAllCookies(null);WebStorage.getInstance().deleteAllData();LinearLayout l=new LinearLayout(this);l.setOrientation(1);TextView warning=new TextView(this);warning.setText("Private session • cookies, DOM storage and cache disabled. Sites and network providers can still see activity.");l.addView(warning);address=new EditText(this);address.setSingleLine(true);address.setHint("https://...");l.addView(address);Button go=new Button(this);go.setText("Open HTTPS page");go.setOnClickListener(v->{String url=address.getText().toString().trim();if(allowed(url))web.loadUrl(url);else Toast.makeText(this,"Use HTTPS",Toast.LENGTH_SHORT).show();});l.addView(go);web=new WebView(this);WebSettings s=web.getSettings();s.setCacheMode(WebSettings.LOAD_NO_CACHE);s.setDomStorageEnabled(false);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setJavaScriptEnabled(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setSaveFormData(false);cm.setAcceptThirdPartyCookies(web,false);web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !allowed(r.getUrl().toString());}@Override public void onPageFinished(WebView v,String u){address.setText(u);}});l.addView(web,new LinearLayout.LayoutParams(-1,0,1));setContentView(l);}
 boolean allowed(String u){try{HttpEngine.validated(u,false);return true;}catch(Exception e){return false;}}
 @Override public void onBackPressed(){if(web.canGoBack())web.goBack();else super.onBackPressed();}
 @Override protected void onDestroy(){if(web!=null){web.stopLoading();web.clearHistory();web.clearCache(true);web.clearFormData();if(web.getParent()!=null)((android.view.ViewGroup)web.getParent()).removeView(web);web.destroy();}CookieManager.getInstance().removeAllCookies(null);WebStorage.getInstance().deleteAllData();super.onDestroy();}
}